```cpp
#include <vector>
#include <iostream>

int main() {
  std::vector<int> v; // Creates an empty vector
  std::cout << "Initial size: " << v.size() << std::endl; //Prints 0

  v.push_back(10); // Add elements
  v.push_back(20);
  v.push_back(30);

  std::cout << "Size after additions: " << v.size() << std::endl; //Prints 3

  for (size_t i = 0; i < v.size(); ++i) { // Iterate safely using size()
    std::cout << "Element at index " << i << ": " << v[i] << std::endl;
  }

  // Accessing elements using at() for bounds checking
  try {
    std::cout << "Element at index 1: " << v.at(1) << std::endl; // Safe access
    std::cout << "Element at index 3: " << v.at(3) << std::endl; // Throws exception
  } catch (const std::out_of_range& oor) {
    std::cerr << "Out of Range error: " << oor.what() << std::endl;
  }

  return 0;
}
